+				SubConn:           sc,
+				logger:            b.logger,
+				connectivityState: connectivity.Idle,
+			}
+			b.subConns.Set(addr, wsc)
+			b.scMap[sc] = wsc
+			b.csEvltr.RecordTransition(connectivity.Shutdown, connectivity.Idle)
+			sc.Connect()
+		}
