+	lbCfg := &lbConfig{
+		// Default values as documented in A58.
+		OOBReportingPeriod:     10 * time.Second,
+		BlackoutPeriod:         10 * time.Second,
+		WeightExpirationPeriod: 3 * time.Minute,
